CREATE TABLE user_account (id BIGINT NOT NULL AUTO_INCREMENT,user_name VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,display_name VARCHAR(128) NULL,password_hash CHAR(60) CHARACTER SET ascii COLLATE ascii_bin NULL,role VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'user',status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_user_account_name UNIQUE(user_name),CONSTRAINT ck_user_account_role CHECK(role IN ('user','admin')),CONSTRAINT ck_user_account_status CHECK(status IN ('active','disabled')),CONSTRAINT ck_user_account_name CHECK(REGEXP_LIKE(user_name,'^[a-z0-9_]{3,32}$','c')),CONSTRAINT ck_user_account_display CHECK(display_name IS NULL OR CHAR_LENGTH(TRIM(display_name)) BETWEEN 1 AND 64)) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
